 "", "opcoes": [{"id": "shake", "nome": "Sabor do milkshake", "min": 1, "max": 1, "itens": [{"id": "s1", "nome": "Baunilha", "preco": 0}, {"id": "s2", "nome": "Chocolate belga", "preco": 0}, {"id": "s3", "nome": "Morango", "preco": 0}, {"id": "s4", "nome": "Doce de leite", "preco": 3}]}]}, {"nome": "Refrigerante lata", "desc": "350 ml, bem gelado.", "preco": 7, "unid": "", "foto": "", "destaque": false, "selo": "", "opcoes": [{"id": "refri", "nome": "Sabor do refrigerante", "min": 1, "max": 1, "itens": [{"id": "r1", "nome": "Coca-Cola", "preco": 0}, {"id": "r2", "nome": "Coca-Cola Zero", "preco": 0}, {"id": "r3", "nome": "Guaraná Antarctica", "preco": 0}]}]}, {"nome": "Água com ou sem gás", "desc": "500 ml.", "preco": 5, "unid": "", "foto": "", "destaque": false, "selo": "", "opcoes": [{"id": "agua", "nome": "Escolha", "min": 1, "max": 1, "itens": [{"id": "g1", "nome": "Sem gás", "preco": 0}, {"id": "g2", "nome": "Com gás", "preco": 0}]}]}]}, {"nome": "Sobremesas", "itens": [{"nome": "Petit gâteau", "desc": "Bolinho de chocolate com centro cremoso e sorvete de baunilha.", "preco": 24, "unid": "", "foto": "/assets/img/exemplo/petit-gateau.jpg", "destaque": false, "selo": "", "opcoes": []}, {"nome": "Cheesecake basco", "desc": "Fatia cremosa, de casca caramelizada.", "preco": 22, "unid": "", "foto": "/assets/img/exemplo/cheesecake-basco.jpg", "destaque": false, "selo": "", "opcoes": []}]}]'::jsonb;
  c jsonb; p jsonb; cid text; pos int := 0; k int;
begin
  select id into v_loja from public.lojas where slug = 'hamburgueria';
  if v_loja is null then
    select id into v_pad from public.lojas where slug = 'padaria';
    insert into public.lojas (slug, store_name, modelo, criado_por)
    values ('hamburgueria', 'Bruto Burger', 'hamburgueria', (select criado_por from public.lojas where id = v_pad))
    returning id into v_loja;
    if v_pad is not null then
      insert into public.membros (loja_id, user_id, papel, email)
      select v_loja, m.user_id, m.papel, m.email from public.membros m where m.loja_id = v_pad
      on conflict (loja_id, user_id) do nothing;
    end if;
  end if;

  update public.lojas set
    store_name = 'Bruto Burger', modelo = 'hamburgueria', descricao = 'Hamburgueria artesanal na brasa. Blends de 160 g, pão brioche e molhos feitos aqui.',
    whatsapp = '5542999006578', address = 'Rua Exemplo, 123 · Centro', hours = 'Ter a dom · 18h às 23h30',
    instagram = '@brutoburger', cor = '#E0301E',
    logo_url = '/assets/img/exemplo/bruto/logo.png', capa_url = '/assets/img/exemplo/bruto/hero.jpg',
    delivery_fee = 7.0, min_order = 0.0,
    accept_orders = true, faz_entrega = true, faz_retirada = true, pagamentos = array['Pix','Cartão','Dinheiro'], status = 'ativa',
    extra = coalesce(extra, '{}'::jsonb) || '{"secoes": {"sobre": {"titulo": "Na brasa, do nosso jeito", "texto": "Cada blend é moldado na hora e vai direto para a brasa.\nPão brioche selado, queijo que derrete de verdade e molhos preparados aqui, todos os dias.", "foto": "/assets/img/exemplo/bruto/fogo.jpg"}, "galeria": {"fotos": ["/assets/img/exemplo/bruto/classico.jpg", "/assets/img/exemplo/bruto/barbecue.jpg", "/assets/img/exemplo/bruto/trufado.jpg", "/assets/img/exemplo/bruto/mexicano.jpg", "/assets/img/exemplo/bruto/crispy.jpg", "/assets/img/exemplo/bruto/batata.jpg"]}}}'::jsonb
  where id = v_loja;

  delete from public.products where loja_id = v_loja;
  delete from public.categories where loja_id = v_loja;
  for c in select * from jsonb_array_elements(cardapio) loop
    pos := pos + 1;
    insert into public.categories (loja_id, name, position) values (v_loja, c ->> 'nome', pos) returning id into cid;
    k := 0;
    for p in select * from jsonb_array_elements(c -> 'itens') loop
      k := k + 1;
      insert into public.products (loja_id, category_id, name, description, price, unit, image_url, active, featured, badge, position, opcoes)
      values (v_loja, cid, p ->> 'nome', coalesce(p ->> 'desc', ''), (p ->> 'preco')::numeric, coalesce(p ->> 'unid', ''),
              coalesce(p ->> 'foto', ''), true, coalesce((p ->> 'destaque')::boolean, false), coalesce(p ->> 'selo', ''), k,
              coalesce(p -> 'opcoes', '[]'::jsonb));
    end loop;
  end loop;
  raise notice 'Pronto: % com % categorias e % produtos.', 'Bruto Burger', pos, (select count(*) from public.products where loja_id = v_loja);
end $$;
